Title: PKA ECC DoubleBaseLadder RAM offsets overlap inputs/outputs -> invalid secp256r1 point on STM32H7S3L8

Body:
**Goal**
I want to use mbedtls_ecdsa_genkey to accelerate the TLS handshake, but I can't implement this function on STM32. 
However, I have successfully implemented mbedtls_ecdsa_sign and mbedtls_ecdsa_verify.

I would like to confirm whether it is possible to generate a private key on the STM32H7S3L8?
Don't worry about whether the example is based on Zephyr; it can be based on STMCubeiDE or any IDE.

### Environment
- Target MCU: STM32H7S3L8
- Board: NUCLEO-H7S3L8 (Zephyr board: nucleo_h7s3l8, adjust if different)
- Zephyr: (23892b038f6a94f6677318fecbc4df98fc8e2ac5)
- hal_stm32: 9325b43737ffca79ffe1af6300c90ffde98919da
  https://github.com/zephyrproject-rtos/hal_stm32
- Crypto library: mbedTLS (Zephyr integrated)

### Summary
When using STM32 PKA HAL ECC Double Base Ladder mode to compute Q = d*G on secp256r1,
HAL_PKA_ECCDoubleBaseLadder() returns HAL_OK but the produced (X,Y) is not a valid
secp256r1 public key point (mbedtls_ecp_check_pubkey fails).

The HAL defines overlapping PKA RAM offsets for this mode:
- input k overlaps output error
- input m overlaps output X

This makes correct computation impossible / results corrupted.

Evidence (overlapping macros)
From the STM32 PKA HAL (stm32h7rsxx_hal_pka.c or related private header), Double Base Ladder offsets:

Inputs:
#define PKA_ECC_DOUBLE_LADDER_IN_K_INTEGER   ((0x0520UL - PKA_RAM_OFFSET)>>2)
#define PKA_ECC_DOUBLE_LADDER_IN_M_INTEGER   ((0x0578UL - PKA_RAM_OFFSET)>>2)

Outputs:
#define PKA_ECC_DOUBLE_LADDER_OUT_ERROR      ((0x0520UL - PKA_RAM_OFFSET)>>2)
#define PKA_ECC_DOUBLE_LADDER_OUT_RESULT_X   ((0x0578UL - PKA_RAM_OFFSET)>>2)
#define PKA_ECC_DOUBLE_LADDER_OUT_RESULT_Y   ((0x05D0UL - PKA_RAM_OFFSET)>>2)

Overlaps:
- 0x0520 is both IN_K_INTEGER and OUT_ERROR
- 0x0578 is both IN_M_INTEGER and OUT_RESULT_X

### Reproduction
 (minimal)
1. Use secp256r1 parameters (p, a=-3, b, Gx, Gy, n).
2. Generate random private key d in [1, n-1].
3. Call HAL_PKA_ECCDoubleBaseLadder with:
   - modulusSize = 32, primeOrderSize = 32
   - coefA = |a| = 3, coefSign = 1 (a = -3)
   - modulus = p
   - integerK = d (32 bytes, big-endian)
   - integerM = 0 (32 bytes, big-endian)
   - P1 = G with Z1 = 1
   - P2 = G with Z2 = 1 (m=0 so P2 should not matter)
4. Read X/Y using HAL_PKA_ECCDoubleBaseLadder_GetResult().
5. Load X/Y into mbedTLS point Q and run:
   ret = mbedtls_ecp_check_pubkey(&grp, &Q);

Expected behavior
- mbedtls_ecp_check_pubkey() returns 0 (Q is valid secp256r1 point)

Actual behavior
- HAL_PKA_ECCDoubleBaseLadder returns HAL_OK
- mbedtls_ecp_check_pubkey() returns -19584 (invalid public key)
- ECDSA verify with this public key fails accordingly.

c
#include <string.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(ecdsa_alt, LOG_LEVEL_DBG);

#include <stm32h7rsxx_hal.h>
#include <stm32h7rsxx_hal_pka.h>

#include <mbedtls/ecdsa.h>
#include <mbedtls/ecp.h>
#include <mbedtls/bignum.h>
#include <mbedtls/platform_util.h>

/* mbedTLS 3.x compatibility */
#ifndef MBEDTLS_PRIVATE
#define MBEDTLS_PRIVATE(member) member
#endif

#define ECDSA_CTX_GRP(ctx)   ((ctx)->MBEDTLS_PRIVATE(grp))
#define ECDSA_CTX_D(ctx)     ((ctx)->MBEDTLS_PRIVATE(d))
#define ECDSA_CTX_Q(ctx)     ((ctx)->MBEDTLS_PRIVATE(Q))

#define ECP_POINT_X(P)       ((P).MBEDTLS_PRIVATE(X))
#define ECP_POINT_Y(P)       ((P).MBEDTLS_PRIVATE(Y))
#define ECP_POINT_Z(P)       ((P).MBEDTLS_PRIVATE(Z))

/* Use a local error for "HW accel failed" (avoid abusing ALLOC_FAILED). */
#ifndef MBEDTLS_ERR_PLATFORM_HW_ACCEL_FAILED
#define MBEDTLS_ERR_PLATFORM_HW_ACCEL_FAILED  (-0x7F00)
#endif

/* secp256r1 constants (big-endian) */
static const uint8_t secp256r1_p[32] = {
    0xff,0xff,0xff,0xff, 0x00,0x00,0x00,0x01,
    0x00,0x00,0x00,0x00, 0x00,0x00,0x00,0x00,
    0x00,0x00,0x00,0x00, 0x00,0x00,0x00,0x00,
    0xff,0xff,0xff,0xff, 0xff,0xff,0xff,0xff
};

/* |a| = 3 (a = -3) */
static const uint8_t secp256r1_a_abs[32] = {
    0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
    0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x03
};

static const uint8_t secp256r1_Gx[32] = {
    0x6B,0x17,0xD1,0xF2,0xE1,0x2C,0x42,0x47,0xF8,0xBC,0xE6,0xE5,0x63,0xA4,0x40,0xF2,
    0x77,0x03,0x7D,0x81,0x2D,0xEB,0x33,0xA0,0xF4,0xA1,0x39,0x45,0xD8,0x98,0xC2,0x96
};

static const uint8_t secp256r1_Gy[32] = {
    0x4F,0xE3,0x42,0xE2,0xFE,0x1A,0x7F,0x9B,0x8E,0xE7,0xEB,0x4A,0x7C,0x0F,0x9E,0x16,
    0x2B,0xCE,0x33,0x57,0x6B,0x31,0x5E,0xCE,0xCB,0xB6,0x40,0x68,0x37,0xBF,0x51,0xF5
};

/* Global PKA handle (simple blocking use) */
static PKA_HandleTypeDef hpka = { .Instance = PKA, .State = HAL_PKA_STATE_READY };
static int pka_inited;

int mbedtls_ecdsa_genkey( mbedtls_ecdsa_context *ctx,
                          mbedtls_ecp_group_id gid,
                          int (*f_rng)(void *, unsigned char *, size_t),
                          void *p_rng )
{
    int ret = 0;

    LOG_INF("genkey enter: gid=%d", (int)gid);

    if (ctx == NULL || f_rng == NULL) {
        LOG_ERR("genkey bad input");
        return MBEDTLS_ERR_ECP_BAD_INPUT_DATA;
    }

    if (gid != MBEDTLS_ECP_DP_SECP256R1) {
        LOG_ERR("genkey unsupported curve gid=%d", (int)gid);
        return MBEDTLS_ERR_ECP_FEATURE_UNAVAILABLE;
    }

    ret = mbedtls_ecp_group_load(&ECDSA_CTX_GRP(ctx), gid);
    if (ret != 0) {
        LOG_ERR("mbedtls_ecp_group_load ret=%d", ret);
        return ret;
    }

    uint8_t d_buf[32];
    uint8_t x_out[32];
    uint8_t y_out[32];

    uint8_t qx_buf[32];
    uint8_t qy_buf[32];

    uint8_t zero32[32];
    uint8_t one32[32];

    mbedtls_mpi d_mpi;
    mbedtls_mpi_init(&d_mpi);

    memset(d_buf, 0, sizeof(d_buf));
    memset(x_out, 0, sizeof(x_out));
    memset(y_out, 0, sizeof(y_out));
    memset(qx_buf, 0, sizeof(qx_buf));
    memset(qy_buf, 0, sizeof(qy_buf));

    memset(zero32, 0, sizeof(zero32));
    memset(one32,  0, sizeof(one32));
    one32[31] = 1; /* big-endian 1 */

    /* Generate private key d in [1, N-1] */
    for (unsigned attempt = 0; attempt < 100; attempt++) {
        ret = f_rng(p_rng, d_buf, sizeof(d_buf));
        if (ret != 0) {
            LOG_ERR("f_rng failed");
            ret = MBEDTLS_ERR_ECP_RANDOM_FAILED;
            goto cleanup;
        }

        ret = mbedtls_mpi_read_binary(&d_mpi, d_buf, sizeof(d_buf));
        if (ret != 0) {
            goto cleanup;
        }

        if (mbedtls_mpi_cmp_int(&d_mpi, 0) == 0) {
            continue;
        }

        if (mbedtls_mpi_cmp_mpi(&d_mpi, &ECDSA_CTX_GRP(ctx).N) >= 0) {
            continue;
        }

        break;
    }

    if (mbedtls_mpi_cmp_int(&d_mpi, 0) == 0 ||
        mbedtls_mpi_cmp_mpi(&d_mpi, &ECDSA_CTX_GRP(ctx).N) >= 0) {
        LOG_ERR("failed to generate valid private key d");
        ret = MBEDTLS_ERR_ECP_RANDOM_FAILED;
        goto cleanup;
    }

    /* Hardware: Q = d*G using DoubleBaseLadder: R = k*P1 + m*P2 with m=0 */
    {
        PKA_ECCDoubleBaseLadderInTypeDef in;
        PKA_ECCDoubleBaseLadderOutTypeDef out;

        memset(&in, 0, sizeof(in));
        memset(&out, 0, sizeof(out));

        in.primeOrderSize = 32;
        in.modulusSize    = 32;

        /* P-256: a = -3 => coefSign=1, |a|=3 */
        in.coefSign = 1;
        in.coefA    = secp256r1_a_abs;
        in.modulus  = secp256r1_p;

        in.integerK = d_buf;
        in.integerM = zero32;

        in.basePointX1 = secp256r1_Gx;
        in.basePointY1 = secp256r1_Gy;
        in.basePointZ1 = one32;

        /* P2 doesn't matter when m=0 */
        in.basePointX2 = secp256r1_Gx;
        in.basePointY2 = secp256r1_Gy;
        in.basePointZ2 = one32;

        out.ptX = x_out;
        out.ptY = y_out;

        LOG_DBG("calling HAL_PKA_ECCDoubleBaseLadder (Q=d*G)...");
        if (HAL_PKA_ECCDoubleBaseLadder(&hpka, &in, 5000) != HAL_OK) {
            uint32_t he = HAL_PKA_GetError(&hpka);
            LOG_ERR("HAL_PKA_ECCDoubleBaseLadder failed: hal_err=0x%08x state=%d CR=0x%08x SR=0x%08x",
                    (unsigned)he, (int)HAL_PKA_GetState(&hpka),
                    (unsigned)hpka.Instance->CR, (unsigned)hpka.Instance->SR);
            ret = MBEDTLS_ERR_PLATFORM_HW_ACCEL_FAILED;
            goto cleanup;
        }

        HAL_PKA_ECCDoubleBaseLadder_GetResult(&hpka, &out);

        memcpy(qx_buf, x_out, 32);
        memcpy(qy_buf, y_out, 32);
    }

    /* Write key into ctx */
    ret = mbedtls_mpi_read_binary(&ECDSA_CTX_D(ctx), d_buf, sizeof(d_buf));
    if (ret != 0) {
        goto cleanup;
    }

    ret = mbedtls_mpi_read_binary(&ECP_POINT_X(ECDSA_CTX_Q(ctx)), qx_buf, sizeof(qx_buf));
    if (ret != 0) {
        goto cleanup;
    }

    ret = mbedtls_mpi_read_binary(&ECP_POINT_Y(ECDSA_CTX_Q(ctx)), qy_buf, sizeof(qy_buf));
    if (ret != 0) {
        goto cleanup;
    }

    ret = mbedtls_mpi_lset(&ECP_POINT_Z(ECDSA_CTX_Q(ctx)), 1);
    if (ret != 0) {
        goto cleanup;
    }

    /* These two logs match your sample output */
    ret = mbedtls_ecp_check_pubkey(&ECDSA_CTX_GRP(ctx), &ECDSA_CTX_Q(ctx));
    LOG_INF("mbedtls_ecp_check_pubkey ret=%d", ret);
    if (ret != 0) {
        LOG_ERR("generated public key is invalid for P-256");
        goto cleanup;
    }

    LOG_INF("genkey ok (double-base ladder)");
    ret = 0;

cleanup:
    mbedtls_platform_zeroize(d_buf, sizeof(d_buf));
    mbedtls_platform_zeroize(qx_buf, sizeof(qx_buf));
    mbedtls_platform_zeroize(qy_buf, sizeof(qy_buf));
    mbedtls_mpi_free(&d_mpi);
    return ret;
}


